import AppKit
import CryptoKit

/// Watches the general pasteboard and records each new copy in the history.
final class ClipboardMonitor {
    /// Markers that password managers and other apps add to say "don't save this".
    /// See https://nspasteboard.org
    static let privateTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
    ]

    /// Added by macOS to copies that arrive through Universal Clipboard. It holds no data,
    /// so there's no way to tell which device sent the copy.
    static let universalClipboardType = "com.apple.is-remote-clipboard"

    private let pasteboard = NSPasteboard.general
    private let store: HistoryStore
    private var lastChangeCount: Int
    private var pollTask: Task<Void, Never>?

    init(store: HistoryStore) {
        self.store = store
        lastChangeCount = pasteboard.changeCount
    }

    func start() {
        guard pollTask == nil else { return }
        // Ignore whatever was on the clipboard before launch.
        lastChangeCount = pasteboard.changeCount
        pollTask = Task { [weak self] in
            while !Task.isCancelled {
                self?.checkForChanges()
                // The tolerance lets macOS group wake-ups, which saves energy.
                try? await Task.sleep(for: .milliseconds(500), tolerance: .milliseconds(250))
            }
        }
    }

    func stop() {
        pollTask?.cancel()
        pollTask = nil
    }

    private func checkForChanges() {
        let changeCount = pasteboard.changeCount
        guard changeCount != lastChangeCount else { return }
        // Apps clear the pasteboard before writing to it. If we look in between,
        // it's empty, so try again on the next check instead of missing the copy.
        guard pasteboard.types?.isEmpty == false else { return }
        lastChangeCount = changeCount
        if let item = readItem() {
            store.add(item)
        }
    }

    // MARK: - Reading

    private func readItem() -> ClipItem? {
        guard let types = pasteboard.types, !types.isEmpty else { return nil }
        let typeIDs = Set(types.map(\.rawValue))
        guard typeIDs.isDisjoint(with: Self.privateTypes) else { return nil }

        // The frontmost app didn't make a copy that came from another device.
        let isRemote = typeIDs.contains(Self.universalClipboardType)
        let app = isRemote ? nil : NSWorkspace.shared.frontmostApplication
        func item(_ kind: ClipItem.Kind, _ text: String, key: String? = nil, image: String? = nil) -> ClipItem {
            ClipItem(kind: kind, text: text, imageFileName: image, contentKey: key ?? text,
                     sourceAppName: app?.localizedName, sourceBundleID: app?.bundleIdentifier,
                     origin: isRemote ? .otherDevice : .thisMac)
        }

        // A colour from a colour picker or the Colors panel.
        if types.contains(.color), let color = NSColor(from: pasteboard), let hex = color.hexString {
            return item(.color, hex)
        }

        // Files copied in Finder.
        if let urls = pasteboard.readObjects(forClasses: [NSURL.self], options: [.urlReadingFileURLsOnly: true]) as? [URL],
           let url = urls.first {
            return item(.link, url.absoluteString)
        }

        // Text, which might be a link or a hex colour.
        if let string = pasteboard.string(forType: .string) {
            let trimmed = string.trimmingCharacters(in: .whitespacesAndNewlines)
            guard !trimmed.isEmpty else { return nil }
            if ClipItem.isHexColor(trimmed) { return item(.color, trimmed.uppercased()) }
            if ClipItem.isLink(trimmed) { return item(.link, trimmed) }
            var text = item(.text, string)
            // Keep any formatting so "Paste" can restore it.
            if let existing = store.item(withContentKey: string) {
                text.richTextFileName = existing.richTextFileName
            } else if let type = [NSPasteboard.PasteboardType.rtf, .html].first(where: types.contains),
                      let data = pasteboard.data(forType: type) {
                text.richTextFileName = store.saveRichText(data, type: type)
            }
            return text
        }

        // Images, such as screenshots or "Copy Image" in a browser.
        if let data = pasteboard.data(forType: .png) ?? pasteboard.data(forType: .tiff) {
            let key = "image:" + SHA256.hash(data: data).map { String(format: "%02x", $0) }.joined()
            // Already in the history: just move it up, without saving the file again.
            if let existing = store.item(withContentKey: key) {
                return item(.image, existing.text, key: key, image: existing.imageFileName)
            }
            guard let saved = store.saveImage(data) else { return nil }
            return item(.image, "Image \(saved.width) × \(saved.height)", key: key, image: saved.fileName)
        }

        // A link with no plain-text version.
        if let url = NSURL(from: pasteboard) as URL? {
            return item(.link, url.absoluteString)
        }

        return nil
    }

    // MARK: - Writing

    /// Puts an item back on the clipboard and moves it to the top of the history.
    /// With `asPlainText`, formatting and link data are left out.
    func copy(_ item: ClipItem, asPlainText: Bool = false) {
        pasteboard.clearContents()
        switch item.kind {
        case .text, .color:
            pasteboard.setString(item.text, forType: .string)
            if !asPlainText, let rich = store.richText(for: item) {
                pasteboard.setData(rich.data, forType: rich.type)
            }
        case .link:
            let url = URL(string: item.text)
            if !asPlainText, let url {
                pasteboard.writeObjects([url as NSURL])
            }
            if asPlainText || url?.isFileURL != true {
                pasteboard.setString(asPlainText ? item.displayText : item.text, forType: .string)
            }
        case .image:
            if let url = store.imageURL(for: item), let image = NSImage(contentsOf: url) {
                pasteboard.writeObjects([image])
            }
        }
        // Don't record our own change as a new copy.
        lastChangeCount = pasteboard.changeCount
        store.markUsed(item)
    }
}

private extension NSColor {
    /// "#RRGGBB" in sRGB, or nil for pattern colours that have no single value.
    var hexString: String? {
        guard let rgb = usingColorSpace(.sRGB) else { return nil }
        let r = Int((rgb.redComponent * 255).rounded())
        let g = Int((rgb.greenComponent * 255).rounded())
        let b = Int((rgb.blueComponent * 255).rounded())
        return String(format: "#%02X%02X%02X", r, g, b)
    }
}
